def new(name,date,source,loc,d,cats=[],desc='',prev=None,end=None,reg=None,opens=None,**kw):
 id=existing_ids.get(name,str(uuid.uuid4()));patch={'name':name,'start_date':date,'end_date':end,'website_url':source,'location_id':loc,'disciplines':d,'formats':[x for x in d if x in ['xcm','mtbo','tt','road_race']],'status':'scheduled','visibility':'public','season':'2027','source_kind':'official','event_type':'race','competition_type':'community','audience':'adults','age_categories':[],'age_confidence':None,'level':'local','description':desc,'registration_url':reg,'registration_opens_at':opens}
 if kw.get('location'):patch.pop('location_id')
 add(id,source,patch,cats,note=kw.pop('note','Official 2027 announcement; no historical edition-specific data cloned.'),previous_id=prev,**kw)
 return plan[-1]
